00, '2012:1333008900:1333009500', 600, 'lt_1h' UNION ALL SELECT 1333009500, 1333010100, '2012:1333009500:1333010100', 600, 'lt_1h' UNION ALL SELECT 1333010100, 1333010700, '2012:1333010100:1333010700', 600, 'lt_1h' UNION ALL SELECT 1333010700, 1333011300, '2012:1333010700:1333011300', 600, 'lt_1h' UNION ALL SELECT 1333011300, 1333011900, '2012:1333011300:1333011900', 600, 'lt_1h' UNION ALL SELECT 1333011900, 1333012500, '2012:1333011900:1333012500', 600, 'lt_1h' UNION ALL SELECT 1333012500, 1333013100, '2012:1333012500:1333013100', 600, 'lt_1h' UNION ALL SELECT 1333013100, 1333013700, '2012:1333013100:1333013700', 600, 'lt_1h' UNION ALL SELECT 1333013700, 1333014300, '2012:1333013700:1333014300', 600, 'lt_1h' UNION ALL SELECT 1333014300, 1333014900, '2012:1333014300:1333014900', 600, 'lt_1h' UNION ALL SELECT 1333014900, 1333015500, '2012:1333014900:1333015500', 600, 'lt_1h' UNION ALL SELECT 1333015500, 1333016100, '2012:1333015500:1333016100', 600, 'lt_1h' UNION ALL SELECT 1333016100, 1333016700, '2012:1333016100:1333016700', 600, 'lt_1h' UNION ALL SELECT 1333016700, 1333017300, '2012:1333016700:1333017300', 600, 'lt_1h' UNION ALL SELECT 1333017300, 1333017900, '2012:1333017300:1333017900', 600, 'lt_1h' UNION ALL SELECT 1333017900, 1333018500, '2012:1333017900:1333018500', 600, 'lt_1h' UNION ALL SELECT 1333018500, 1333019100, '2012:1333018500:1333019100', 600, 'lt_1h' UNION ALL SELECT 1333019100, 1333019700, '2012:1333019100:1333019700', 600, 'lt_1h' UNION ALL SELECT 1333019700, 1333020300, '2012:1333019700:1333020300', 600, 'lt_1h' UNION ALL SELECT 1333020300, 1333020900, '2012:1333020300:1333020900', 600, 'lt_1h' UNION ALL SELECT 1333020900, 1333021500, '2012:1333020900:1333021500', 600, 'lt_1h' UNION ALL SELECT 1333021500, 1333022100, '2012:1333021500:1333022100', 600, 'lt_1h' UNION ALL SELECT 1333022100, 1333022700, '2012:1333022100:1333022700', 600, 'lt_1h' UNION ALL SELECT 1333022700, 1333023300, '2012:1333022700:1333023300', 600, 'lt_1h' UNION ALL SELECT 1333023300, 1333023900, '2012:1333023300:1333023900', 600, 'lt_1h' UNION ALL SELECT 1333023900, 1333024500, '2012:1333023900:1333024500', 600, 'lt_1h' UNION ALL SELECT 1333024500, 1333025100, '2012:1333024500:1333025100', 600, 'lt_1h' UNION ALL SELECT 1333025100, 1333025700, '2012:1333025100:1333025700', 600, 'lt_1h' UNION ALL SELECT 1333025700, 1333026300, '2012:1333025700:1333026300', 600, 'lt_1h' UNION ALL SELECT 1333026300, 1333026900, '2012:1333026300:1333026900', 600, 'lt_1h' UNION ALL SELECT 1333026900, 1333027500, '2012:1333026900:1333027500', 600, 'lt_1h' UNION ALL SELECT 1333027500, 1333028100, '2012:1333027500:1333028100', 600, 'lt_1h' UNION ALL SELECT 1333028100, 1333028700, '2012:1333028100:1333028700', 600, 'lt_1h' UNION ALL SELECT 1333028700, 1333029300, '2012:1333028700:1333029300', 600, 'lt_1h' UNION ALL SELECT 1333029300, 1333029900, '2012:1333029300:1333029900', 600, 'lt_1h' UNION ALL SELECT 1333029900, 1333030500, '2012:1333029900:1333030500', 600, 'lt_1h' UNION ALL SELECT 1333030500, 1333031100, '2012:1333030500:1333031100', 600, 'lt_1h'), wh_hits AS (
 SELECT t.gap_id,t.gap_band,t.left_time,t.right_time,a.dateTime ts,
        a.usUnits wh_units,a.`interval` wh_interval,a.outTemp wh_temp,a.outHumidity wh_rh,
        a.rain wh_rain,a.rainRate wh_rainRate,a.windSpeed wh_wind
 FROM targets t JOIN weewx_WH1080.archive a
   ON a.dateTime>t.left_time AND a.dateTime<t.right_time AND MOD(a.dateTime-t.left_time,300)=0
 LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime
 WHERE r.dateTime IS NULL
)
SELECT CAST(SUBSTRING_INDEX(h.gap_id,':',1) AS UNSIGNED) utc_year,h.gap_band,
 CASE WHEN h.ts>=1514764800 AND h.ts<1522540800 THEN 'PROTECTED_Q1_2018_DIAGNOSTIC' ELSE 'NORMAL' END protection_scope,
 COUNT(*) wh1080_rows,SUM(o.dateTime IS NOT NULL) old_weewx_rows,
 SUM(o.dateTime IS NULL) old_weewx_missing,
 SUM(h.wh_units=17) wh_units17,SUM(h.wh_interval=5) wh_interval5,
 SUM(o.usUnits<=>h.wh_units) units_equal,SUM(o.`interval`<=>h.wh_interval) intervals_equal,
 SUM(o.outTemp<=>h.wh_temp) outTemp_equal,SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL) outTemp_both_present,
 SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL AND o.outTemp<>h.wh_temp) outTemp_conflict,
 SUM(h.wh_temp=0) wh_outTemp_zero,SUM(h.wh_temp IS NULL) wh_outTemp_null,
 SUM(o.outHumidity<=>h.wh_rh) outHumidity_equal,SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL) outHumidity_both_present,
 SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL AND o.outHumidity<>h.wh_rh) outHumidity_conflict,
 SUM(h.wh_rh IS NULL) wh_outHumidity_null,
 SUM(o.rain<=>h.wh_rain) rain_equal,SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL) rain_both_present,
 SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL AND o.rain<>h.wh_rain) rain_conflict,
 SUM(h.wh_rain IS NULL) wh_rain_null,
 SUM(o.rainRate<=>h.wh_rainRate) rainRate_equal,SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL) rainRate_both_present,
 SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL AND o.rainRate<>h.wh_rainRate) rainRate_conflict,
 SUM(h.wh_rainRate IS NULL) wh_rainRate_null,
 SUM(o.windSpeed<=>h.wh_wind) windSpeed_equal,SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL) windSpeed_both_present,
 SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL AND o.windSpeed<>h.wh_wind) windSpeed_conflict,
 SUM(h.wh_wind IS NULL) wh_windSpeed_null
FROM wh_hits h LEFT JOIN old_weewx.archive o ON o.dateTime=h.ts
GROUP BY utc_year,h.gap_band,protection_scope
